"""Print the initial seller prompt generated by the negotiation platform."""

import argparse

from bargaining_platform.engine import NegotiationEngine
from bargaining_platform.prompt_builder import make_private_view, render_prompt
from bargaining_platform.scenario import load_scenario


def main() -> None:
    parser = argparse.ArgumentParser(description="Print the seller agent's prompt")
    parser.add_argument(
        "--scenario",
        default="scenarios/single_product.json",
        help="Path to a scenario JSON file",
    )
    args = parser.parse_args()

    scenario = load_scenario(args.scenario)
    engine = NegotiationEngine(scenario)
    seller_view = make_private_view("buyer", engine.state)
    print(render_prompt("buyer", seller_view))


if __name__ == "__main__":
    main()
